import sqlite3, json
c=sqlite3.connect('file:database.sqlite?mode=ro', uri=True)
queries={
'samples': [('document','SELECT * FROM document LIMIT 6'),('disposition','SELECT * FROM disposition LIMIT 8'),('resolution','SELECT * FROM resolution LIMIT 4'),('meeting','SELECT * FROM meeting LIMIT 6'),('cr_pack','SELECT * FROM cr_pack LIMIT 6'),('section','SELECT * FROM section LIMIT 6')],
'formats': [('disposition_groups','SELECT evidence_status, scope, code, count(*) FROM disposition GROUP BY evidence_status, scope, code'),('meeting_wg','SELECT wg, count(*) FROM meeting GROUP BY wg'),('doc_types','SELECT doc_type, count(*) FROM document GROUP BY doc_type'),('section_release','SELECT release, count(*) FROM section GROUP BY release'),('doc_releases','SELECT target_release, count(*) FROM document GROUP BY target_release')]}
for family, group in queries.items():
 for name, q in group:
  cur=c.execute(q)
  print(name, [v[0] for v in cur.description], json.dumps(cur.fetchall(), ensure_ascii=False))
PY"

