/bin/bash -lc "python3 - <<'PY'
import json,re,sqlite3
with open('packet.json') as f:p=json.load(f)
c=sqlite3.connect('file:database.sqlite?mode=ro',uri=True)
qs={
'release_mismatches': \"SELECT d.number, d.target_release, s.release, s.spec, s.clause FROM cr_modifies_section e JOIN document d ON d.id=e.cr JOIN section s ON s.id=e.section_id WHERE d.target_release IS NOT s.release\",
'pack_columns_comparison': \"SELECT count(*) FROM document d WHERE d.pack_field IS NOT NULL AND NOT EXISTS (SELECT 1 FROM cr_in_pack x JOIN cr_pack p ON p.id=x.pack_id WHERE x.cr=d.id AND p.pack_number=d.pack_field) AND NOT EXISTS (SELECT 1 FROM pack_member x JOIN cr_pack p ON p.id=x.pack_id WHERE x.cr=d.id AND p.pack_number=d.pack_field)\"
}
for name,q in qs.items():print(name,json.dumps(c.execute(q).fetchall()))
families={}
for x in p['items']:
 q=re.sub(r'R1-\\d+|RP-\\d+|Rel-\\d+|\\b\\d+(?:\\.[\\dA-Za-z]+)*\\b','VALUE',x['question'])
 families[q]=families.get(q,0)+1
print('FAMILIES')
for k,v in families.items():print(v,k)
PY"

